-- returns the group and zone to pass to insertDynamicEntity, and the HP to give the monster (0 = leave it)
return function(group, zone, name)
    local v = (name and byName[name]) or map[string.format('%d:%d', zone or 0, group or 0)]
    if v then
        return v[2], v[1], v[4]
    end

    return group, zone, 0
end
